/**
 * BOOT / AUTH (GDD §12.1).
 *
 * The first thing anyone sees, so it earns its frame: a drifting starfield, a
 * live nebula, a rotating command sigil, the wordmark assembling out of
 * scanlines with a chromatic tear, and a telemetry log that types itself out of
 * the *real* world state before handing over a call-sign field.
 *
 * Tap anywhere to fast-forward the sequence.
 */
import '../../styles/boot.css';

import type { IBackend } from '../../backend/IBackend';
import { defaultCommanderName } from '../../backend/names';
import { BATTLE, DRONES, ECONOMY, FORTS, FORT_RULES, SEASON } from '../../config';
import { hashString, makeRng, randomSeed } from '../../game/rng';
import { setScreen, game } from '../../game/store';
import type { GameState } from '../../game/types';
import { button, iconButton, ICONS, panel, toast } from '../components';
import { Disposer, el, fmtDuration, fmtNum, haptic, svg as svgEl } from '../dom';
import type { Screen } from '../screen';

const CHARS_PER_SEC = 190;
const LINE_PAUSE_MS = 70;
const MAX_NAME = 20;

// ─────────────────────────────────────────────────────────────────────────────
// Backdrop
// ─────────────────────────────────────────────────────────────────────────────

const STAR_TILE = 2000;

function starShadow(seed: number, count: number, palette: string[]): string {
  const rng = makeRng(seed >>> 0);
  const parts: string[] = [];
  for (let i = 0; i < count; i++) {
    const x = rng.int(0, STAR_TILE);
    const y = rng.int(0, STAR_TILE);
    parts.push(`${x}px ${y}px 0 ${palette[rng.int(0, palette.length - 1)]}`);
  }
  return parts.join(',');
}

function starLayer(seed: number, count: number, size: number, durationS: number, palette: string[]): HTMLElement {
  const shadow = starShadow(seed, count, palette);
  const layer = el('div', {
    class: 'boot__stars',
    style: `--star-size:${size}px;--star-dur:${durationS}s`,
    aria: { hidden: 'true' },
  });
  for (let i = 0; i < 2; i++) {
    layer.appendChild(el('i', { style: `box-shadow:${shadow}` }));
  }
  return layer;
}

/** Concentric counter-rotating hex rings — the command sigil. */
const SIGIL = `<svg viewBox="0 0 200 200" aria-hidden="true">
    <g class="sig sig--slow">
      <path d="M100 12l76 44v88l-76 44-76-44V56z"/>
      <path d="M100 12v18M100 170v18M24 56l16 9M160 135l16 9M176 56l-16 9M40 135l-16 9"/>
    </g>
    <g class="sig sig--mid">
      <path d="M100 38l54 31v62l-54 31-54-31V69z"/>
      <path d="M46 69l54 31 54-31M100 100v62"/>
    </g>
    <g class="sig sig--fast">
      <circle cx="100" cy="100" r="30"/>
      <path d="M100 70v-10M100 140v10M70 100H60M140 100h10"/>
      <path d="M79 79l-7-7M121 121l7 7M121 79l7-7M79 121l-7 7"/>
    </g>
    <g class="sig sig--core">
      <path d="M100 84l14 8v16l-14 8-14-8V92z"/>
    </g>
  </svg>`;

// ─────────────────────────────────────────────────────────────────────────────
// Telemetry
// ─────────────────────────────────────────────────────────────────────────────

function pad(label: string, value: string): string {
  const dots = Math.max(2, 30 - label.length);
  return `${label} ${'.'.repeat(dots)} ${value}`;
}

function telemetry(state: GameState | null): string[] {
  const lines: string[] = [
    'TERRA BELLUM // ORBITAL COMMAND CONSOLE',
    pad('CONSOLE BUILD', '1.0.0-LIVE'),
    pad('UPLINK', 'ESTABLISHED'),
    pad('AUTH CHANNEL', 'ANONYMOUS · UPGRADEABLE'),
  ];

  if (!state) {
    lines.push(pad('WORLD SNAPSHOT', 'PENDING'));
    lines.push(pad('STATUS', 'STAND BY'));
    lines.push('AWAITING COMMANDER CALL-SIGN');
    return lines;
  }

  const hexes = Object.values(state.world.hexes);
  const sectors = Object.values(state.world.sectors);
  const active = sectors.filter((s) => s.state === 'active').length;
  const gas = hexes.filter((h) => h.gas).length;
  const seed = hashString(`${state.season.name}#${state.season.index}`);
  const remain = Math.max(0, state.season.endsAt - state.now);
  const rotation = Math.max(0, state.season.nextRotationAt - state.now);

  lines.push(pad('WORLD SEED', `0x${seed.toString(16).toUpperCase().padStart(8, '0')}`));
  lines.push(pad('HEXES SURVEYED', fmtNum(hexes.length)));
  lines.push(pad('SECTORS CHARTED', `${sectors.length} · ${active} ACTIVE`));
  lines.push(pad('GAS SIGNATURES', String(gas)));
  lines.push(pad('COMMANDERS ON NET', String(Object.keys(state.players).length)));
  lines.push(pad('BANNERS IN FIELD', String(Object.keys(state.guilds).length)));
  lines.push(pad('SEASON', state.season.name));
  lines.push(pad('SEASON CLOCK', fmtDuration(remain)));
  lines.push(pad('NEXT ROTATION', fmtDuration(rotation)));
  lines.push(pad('DICE ENGINE', `${BATTLE.diceCount}d[${BATTLE.diceMin}-${BATTLE.diceMax}] ARMED`));
  lines.push(pad('DRONE CONTROL', `${DRONES.maxPerPlayer} MOTES / COMMANDER`));
  lines.push(pad('STOCKPILE CAP', `${fmtNum(ECONOMY.capMinerals)} M · ${fmtNum(ECONOMY.capGas)} G`));
  lines.push(pad('ALL SYSTEMS', 'NOMINAL'));
  lines.push('AWAITING COMMANDER CALL-SIGN');
  return lines;
}

// ─────────────────────────────────────────────────────────────────────────────
// Briefing
// ─────────────────────────────────────────────────────────────────────────────

interface Pillar {
  index: string;
  title: string;
  body: string;
}

function pillars(): Pillar[] {
  return [
    {
      index: 'I',
      title: 'NOTHING YOU HOLD IS YOURS ALONE',
      body:
        'You harvest into your own stockpile, but you die alone in it. Banners share intel, ship reserves ' +
        'down the line, and answer pings. A commander without a guild is a resource node with opinions.',
    },
    {
      index: 'II',
      title: 'THE GROUND EXPIRES',
      body:
        `Every ${fmtDuration(SEASON.rotationMs)} one sector goes dark and another opens. Both are announced ` +
        `${fmtDuration(SEASON.announceMs)} ahead. Fortifications in a dying sector are dust, columns inside are ` +
        'evacuated, and whoever pre-positioned wins the opening week.',
    },
    {
      index: 'III',
      title: 'THE DICE DECIDE HOW MUCH, NEVER WHAT',
      body:
        `Three dice, ${BATTLE.diceMin}–${BATTLE.diceMax} each, rolled where you can see them — then you assign ` +
        'them. Damage is flat and calculable. Variance is an action budget, not a coin flip. Triple zero is legal, ' +
        'costs you the turn, and is broadcast to your guild.',
    },
    {
      index: 'IV',
      title: 'HOLDING IS A WIN CONDITION',
      body:
        `${FORTS[1].label} opens a production line, ${FORTS[2].label} pays a yield bonus, ${FORTS[3].label} makes ` +
        `attackers sit through a ${fmtDuration(FORT_RULES.siegeMs)} siege and hands your defenders extra hit points. ` +
        'Concede and your survivors walk out at half strength — a beaten army is still an army.',
    },
  ];
}

// ─────────────────────────────────────────────────────────────────────────────
// Screen
// ─────────────────────────────────────────────────────────────────────────────

export function createBootScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen boot' });
  const disposer = new Disposer();

  // ── backdrop ──────────────────────────────────────────────────────────────
  const sky = el('div', { class: 'boot__sky', aria: { hidden: 'true' } });
  sky.appendChild(el('div', { class: 'boot__nebula boot__nebula--a' }));
  sky.appendChild(el('div', { class: 'boot__nebula boot__nebula--b' }));
  sky.appendChild(el('div', { class: 'boot__nebula boot__nebula--c' }));
  sky.appendChild(starLayer(0x51ed01, 150, 1, 190, ['#8fbfe0', '#cfe6ff', '#6f9bc4']));
  sky.appendChild(starLayer(0x51ed02, 70, 2, 130, ['#eaf6ff', '#9fe4ff', '#ffd7a8']));
  sky.appendChild(starLayer(0x51ed03, 22, 3, 90, ['#4de3ff', '#3dffcf', '#ffd15c']));
  sky.appendChild(el('div', { class: 'boot__horizon' }));
  sky.appendChild(el('div', { class: 'boot__grid' }));
  root.appendChild(sky);
  root.appendChild(el('div', { class: 'boot__vignette scanlines grain', aria: { hidden: 'true' } }));

  // ── hero ──────────────────────────────────────────────────────────────────
  const sigil = el('div', { class: 'boot__sigil' });
  sigil.appendChild(svgEl(SIGIL));

  const mark = el(
    'div',
    { class: 'boot__mark' },
    el('span', { class: 'boot__word', text: 'TERRA', data: { text: 'TERRA' } }),
    el('span', { class: 'boot__word boot__word--b', text: 'BELLUM', data: { text: 'BELLUM' } }),
  );

  const tagline = el('div', {
    class: 'boot__tag',
    text: 'PERSISTENT WAR · HEX BY HEX · BANNER BY BANNER',
  });

  const hero = el('div', { class: 'boot__hero' }, sigil, mark, tagline);

  // ── log ───────────────────────────────────────────────────────────────────
  const logBody = el('div', { class: 'boot__log-body mono' });
  const cursor = el('span', { class: 'boot__cursor', text: '█', aria: { hidden: 'true' } });
  const log = el(
    'div',
    { class: 'boot__log' },
    el(
      'div',
      { class: 'boot__log-head' },
      el('span', { class: 'dot dot--on' }),
      el('span', { text: 'SYSTEM ONLINE' }),
      el('span', { class: 'spacer' }),
      el('span', { class: 'boot__skip', text: 'TAP TO SKIP' }),
    ),
    logBody,
  );
  logBody.appendChild(cursor);

  // ── call-sign ─────────────────────────────────────────────────────────────
  const input = el('input', {
    class: 'field__input boot__input',
    attrs: {
      type: 'text',
      maxlength: MAX_NAME,
      placeholder: 'CALL-SIGN',
      autocomplete: 'off',
      spellcheck: 'false',
      enterkeyhint: 'go',
    },
  });

  const reroll = iconButton(ICONS.refresh, {
    variant: 'bare',
    label: 're-roll call-sign',
    onClick: () => {
      input.value = defaultCommanderName(makeRng(randomSeed())).slice(0, MAX_NAME);
      input.classList.remove('is-fresh');
      void input.offsetWidth;
      input.classList.add('is-fresh');
      haptic(8);
    },
  });

  const enter = button('ENTER THE WAR', {
    variant: 'primary',
    wide: true,
    sub: 'ANONYMOUS UPLINK · NO ACCOUNT REQUIRED',
  });

  const form = el(
    'div',
    { class: 'boot__form' },
    el(
      'div',
      { class: 'field boot__field' },
      el('span', { class: 'field__label', text: 'COMMANDER CALL-SIGN' }),
      el('div', { class: 'boot__field-row' }, input, reroll),
    ),
    enter,
  );

  // ── briefing ──────────────────────────────────────────────────────────────
  const brief = panel(
    {
      title: 'STANDING ORDERS',
      subtitle: 'read once — the war does not repeat itself',
      accent: 'var(--gold)',
      class: 'boot__brief panel--tight',
      holo: true,
    },
  );
  const briefBody = brief.querySelector('.panel__body');
  for (const p of pillars()) {
    briefBody?.appendChild(
      el(
        'div',
        { class: 'pillar' },
        el('span', { class: 'pillar__idx display', text: p.index }),
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'pillar__title display', text: p.title }),
          el('p', { class: 'pillar__body', text: p.body }),
        ),
      ),
    );
  }

  const console_ = el('div', { class: 'boot__console' }, hero, log, form, brief);
  root.appendChild(console_);

  // ── typing state ──────────────────────────────────────────────────────────
  let lines: string[] = [];
  let lineIdx = 0;
  let charIdx = 0;
  let pause = 0;
  let done = false;
  let submitting = false;
  let mounted = false;

  const lineNodes: HTMLElement[] = [];

  const pushLine = (): HTMLElement => {
    const node = el('div', { class: 'boot__line' });
    logBody.insertBefore(node, cursor);
    lineNodes.push(node);
    return node;
  };

  const finish = (): void => {
    if (done) return;
    done = true;
    while (lineIdx < lines.length) {
      const node = lineNodes[lineIdx] ?? pushLine();
      node.textContent = lines[lineIdx];
      lineIdx++;
      charIdx = 0;
    }
    logBody.scrollTop = logBody.scrollHeight;
    root.classList.add('boot--ready');
  };

  const reset = (): void => {
    lines = telemetry(game.get());
    lineIdx = 0;
    charIdx = 0;
    pause = 0;
    done = false;
    lineNodes.length = 0;
    while (logBody.firstChild !== cursor && logBody.firstChild) logBody.removeChild(logBody.firstChild);
    root.classList.remove('boot--ready');
  };

  const step = (dt: number): void => {
    if (done) return;
    if (pause > 0) {
      pause -= dt;
      return;
    }
    if (lineIdx >= lines.length) {
      finish();
      return;
    }
    const text = lines[lineIdx];
    const node = lineNodes[lineIdx] ?? pushLine();
    charIdx += (CHARS_PER_SEC * dt) / 1000;
    const shown = Math.min(text.length, Math.floor(charIdx));
    node.textContent = text.slice(0, shown);
    if (shown >= text.length) {
      lineIdx++;
      charIdx = 0;
      pause = LINE_PAUSE_MS;
      logBody.scrollTop = logBody.scrollHeight;
      if (lineIdx >= lines.length) finish();
    }
  };

  // ── submit ────────────────────────────────────────────────────────────────
  const submit = (): void => {
    if (submitting) return;
    const name = input.value.trim();
    if (name.length < 2) {
      input.classList.remove('is-shake');
      void input.offsetWidth;
      input.classList.add('is-shake');
      toast({ title: 'CALL-SIGN REJECTED', body: 'At least two characters, commander.', kind: 'warn' });
      return;
    }
    submitting = true;
    enter.disabled = true;
    root.classList.add('boot--launching');
    haptic([18, 40, 18, 40, 60]);

    void (async () => {
      const res = await backend.signInAnonymous(name);
      if (!res.ok) {
        submitting = false;
        enter.disabled = false;
        root.classList.remove('boot--launching');
        toast({ title: 'UPLINK REFUSED', body: res.error, kind: 'bad' });
        return;
      }
      toast({
        title: `WELCOME, ${res.value.name.toUpperCase()}`,
        body: 'Staging bay open. Choose a landing zone.',
        kind: 'ok',
      });
      window.setTimeout(() => setScreen('map'), 260);
    })();
  };

  enter.addEventListener('click', submit);
  input.addEventListener('keydown', (ev: KeyboardEvent) => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      submit();
    }
  });

  return {
    el: root,

    mount(): void {
      if (mounted) return;
      mounted = true;

      if (input.value.trim().length === 0) {
        input.value = defaultCommanderName(makeRng(randomSeed())).slice(0, MAX_NAME);
      }
      reset();

      disposer.listen(root, 'pointerdown', (ev: PointerEvent) => {
        const target = ev.target as HTMLElement | null;
        if (target?.closest('input, button, .boot__form')) return;
        if (!done) {
          finish();
          haptic(10);
        }
      });
      disposer.listen(window, 'keydown', (ev: KeyboardEvent) => {
        if (ev.key === 'Escape' && !done) finish();
      });
    },

    unmount(): void {
      mounted = false;
      disposer.dispose();
    },

    frame(dt: number): void {
      if (!mounted) return;
      step(dt);
    },
  };
}
